#!/usr/bin/env python3
"""Assemble D46 evidence from completed checks; no synthetic runtime pass flags."""
from pathlib import Path
import json,re,hashlib
r=Path(__file__).resolve().parents[1]
def read(p):return json.loads((r/p).read_text())
cpu=read('validation-d46/xenia/charge-cpu.json');gpu=read('validation-d46/xenia/actions-final.json');long_gpu=read('validation-d46/xenia/charge-gpu-candidate.json');host=read('validation-d46/final/summary.json')
assert cpu['result']==gpu['result']==host['result']=='PASS'
assert gpu['GPU_replay_and_presentation'] and not cpu['GPU_replay_and_presentation']
assert cpu['tested_XEX_sha256']==gpu['tested_XEX_sha256']==hashlib.sha256((r/'xenia/default.xex').read_bytes()).hexdigest()
s=(r/'validation-d46/xenia/actions-final.log').read_text()
candidate_log=(r/'validation-d46/xenia/charge-gpu-candidate.log').read_text()
cache=[{'state_sets':int(a),'state_skips':int(b)} for a,b in re.findall(r'state_sets=(\d+) state_skips=(\d+)',s)]
pressure=[{'sweeps':int(a),'white_fallbacks':int(b)} for a,b in re.findall(r'texture pressure sweeps=(\d+) white_fallbacks=(\d+)',s)]
t=re.search(r'frame times samples=(\d+) min_us=(\d+) median_us=(\d+) p95_us=(\d+) max_us=(\d+) over_33333us=(\d+)',s)
report={'source_delivery':'D46','new_XEX_built':True,'complete_game':False,'NOT_READY':2,'stable_30_fps_verified':False,'native_build':{'console':read('static.json'),'xenia':read('xenia/static.json')},'host_tests':host,'runtime_actions':gpu,'runtime_CPU':cpu,'full_GPU_runtime':gpu,'prolonged_GPU_candidate_before_direct_effect_fix':long_gpu,'direct_effect_packet_tests':read('validation-d46/final/direct-effect/result.json'),'font_tag_fix':read('validation-d46/final/font/result.json'),'live_resource_registry':read('validation-d46/final/resource-leases/result.json'),'texture_pressure_tests':read('validation-d46/final/texture-pressure/result.json'),'VU_FTOI':read('validation-d46/final/ftoi/result.json'),'VU_callback_contracts':read('validation-d46/final/strip/result.json'),'state_cache_counters':cache,'texture_pressure_counters':pressure,'candidate_texture_pressure_counters':[{'sweeps':int(a),'white_fallbacks':int(b)} for a,b in re.findall(r'texture pressure sweeps=(\d+) white_fallbacks=(\d+)',candidate_log)],'direct_effect_packets_final_GPU':[int(v) for v in re.findall(r'direct_effect_packets=(\d+)',s)],'direct_effect_packets_final_CPU':[int(v) for v in re.findall(r'direct_effect_packets=(\d+)',(r/'validation-d46/xenia/charge-cpu.log').read_text())],'software_GPU_frame_times':dict(zip(['samples','min_us','median_us','p95_us','max_us','over_33333us'],map(int,t.groups()))) if t else None,'frame_times_are_physical_console_benchmark':False,'cache_only_pixel_comparison':read('validation-d46/reproduction/cache-pixel-comparison.json'),'commercial_game_data_included':False,'GitHub_published':False,'limitations':['Final XEX GPU probe is 64 FIGHT frames; intermediate prolonged GPU candidate stopped after at least 276 FIGHT frames with host SIGBUS and no clean close','No D46 physical-console FPS measurement; stable 30 FPS unverified','Specific reported visual effect and rectangular impact-flash edge not fully fixed/verified','Held LT is interrupted by opponent AI; uninterrupted charge to MAX POWER not verified','No complete match to KO/results, original-menu flow or indefinite stability; 3600-step limit retained','Stages 1-38, audible audio, saves and online remain unverified','Intermediate cache-only captures are not final-D46 all-effect visual parity proof']}
(r/'RESULTADO-D46.json').write_text(json.dumps(report,indent=2)+'\n')
(r/'SHA256SUMS-D46.txt').write_text(''.join(hashlib.sha256((r/p).read_bytes()).hexdigest()+'  '+p+'\n' for p in ['default.xex','xenia/default.xex']))
print(json.dumps({'source_delivery':'D46','host_tests':host['tests'],'CPU_FIGHT_frames':cpu['FIGHT_frames'],'final_GPU_FIGHT_frames':gpu['FIGHT_frames'],'candidate_GPU_FIGHT_frames':long_gpu['FIGHT_frames'],'last_state_cache':cache[-1] if cache else None,'last_texture_pressure':pressure[-1] if pressure else None},indent=2))
